    unsigned b81 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 1u, 554u, row_index, 0);
    unsigned b1276 = base_params[925u];
    unsigned b1277 = stwo_m31_mul(b81, b1276);
    unsigned b1219 = base_params[849u];
    unsigned b1220 = stwo_m31_mul(b1219, b1101);
    unsigned b1221 = stwo_m31_add(b1220, b1107);
    unsigned b1222 = base_params[850u];
    unsigned b759 = stwo_m31_mul(b731, b745);
    unsigned b1053 = stwo_m31_sub(b759, b123);
    unsigned b1054 = stwo_m31_sub(b1053, b430);
    unsigned b1055 = stwo_m31_add(b389, b1054);
    unsigned b14 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 1u, 26u, row_index, 0);
    unsigned b111 = stwo_m31_add(b14, b14);
    unsigned b62 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 1u, 525u, row_index, 0);
    unsigned b112 = stwo_m31_add(b111, b62);
    unsigned b1108 = stwo_m31_sub(b1055, b112);
    unsigned b1223 = stwo_m31_mul(b1222, b1108);
    unsigned b1224 = stwo_m31_add(b1221, b1223);
    unsigned b1225 = base_params[851u];
    unsigned b614 = stwo_m31_mul(b600, b607);
    unsigned b615 = stwo_m31_sub(b614, b430);
    unsigned b616 = stwo_m31_sub(b615, b515);
    unsigned b617 = stwo_m31_add(b489, b616);
    unsigned b1091 = stwo_m31_sub(b900, b267);
    unsigned b1092 = stwo_m31_sub(b1091, b574);
    unsigned b1093 = stwo_m31_add(b617, b1092);
    unsigned b1226 = stwo_m31_mul(b1225, b1093);
    unsigned b1227 = stwo_m31_sub(b1224, b1226);
    unsigned b1278 = stwo_m31_add(b1227, b80);
    unsigned b1279 = stwo_m31_sub(b1277, b1278);
    StwoCudaQm31 e12 = StwoCudaQm31{ b1279, b82, b82, b82 };
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e12, stwo_load_qm31(random_coeff_powers, rc_base + 12u)));

    // Fused denom_inv multiply + in-place accumulator update.
    unsigned denom_idx = row_index >> log_n_rows;
    StwoCudaQm31 result = stwo_qm31_mul_base(acc, denom_inv[denom_idx]);
    coord_0[row_index] = stwo_m31_add(coord_0[row_index], result.a);
    coord_1[row_index] = stwo_m31_add(coord_1[row_index], result.b);
    coord_2[row_index] = stwo_m31_add(coord_2[row_index], result.c);
    coord_3[row_index] = stwo_m31_add(coord_3[row_index], result.d);
}
